import axiosInstance from "@/api/axiosInstance"

export default function SignupPage() {

    const handleSingup = async () => {
        try {
            const response = await axiosInstance.post('/api/auth/signup', {
                email: '',
                username: '',
                password: '',
            })
            console.log(response.data)
        }
        catch (error) {
            console.error(error)
        }
    }

    return(
        <div className="min-h-screen flex items-center justify-center bg-gray-100 p-6">
            <div className="bg-white shadow-md rounded p-4 w-full max-w-sm">
                <h1 className="text-2xl font-bold mb-4">Signup</h1>
                <form>
                    <div className="mb-4">
                        <label className="block text-sm font-medium text-gray-700">Email</label>
                        <input type="email" className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm
                        " />
                    </div>
                    <div className="mb-4">
                        <label className="block text-sm font-medium text-gray-700">Username</label>
                        <input type="text" className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm
                        " />
                    </div>
                    <div className="mb-6">
                        <label className="block text-sm font-medium text-gray-700">Password</label>
                        <input type="password" className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm
                        " />
                    </div>
                    <button 
                    onClick={handleSingup}
                    className="w-full bg-indigo-500 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline" type="button">
                        Signup
                    </button>
                </form>
            </div>
        </div>
    )
}